pub fn rotate(mut a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return a;
    }
    // Normalize offset in case it's >= n
    let k = offset % n;
    a.rotate_left(k);
    a
}

